func (t Identity) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "ad":
		return t.AsIdentityAd()
	case "entra":
		return t.AsIdentityEntra()
	case "local":
		return t.AsIdentityLocal()
	case "none":
		return t.AsIdentityNone()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

